#include <pybind11/pybind11.h>
#include <pybind11/stl.h>
#include <algorithm>
#include <string>
#include "native_unit_sim.hpp"

namespace py = pybind11;
namespace {
static int as_int(py::handle h,int d=0){try{return py::cast<int>(h);}catch(...){PyErr_Clear();return d;}}
static bool truthy(py::handle h){int r=PyObject_IsTrue(h.ptr());if(r<0)throw py::error_already_set();return r!=0;}
static py::list commands(py::dict action){py::list out;if(action.contains("farmer")&&!action["farmer"].is_none()&&truthy(action["farmer"]))out.append(action["farmer"]);else{py::list p;p.append("PASS");out.append(p);}if(action.contains("hands")&&!action["hands"].is_none()&&truthy(action["hands"]))for(py::handle h:py::cast<py::sequence>(action["hands"]))out.append(h);return out;}
static py::tuple r127_fields(py::dict obs,py::dict action){int player=as_int(obs["player"]),day=as_int(obs["step"])/24;auto farms=py::cast<py::sequence>(obs["farms"]);auto farm=py::cast<py::dict>(kag_unit::clone(farms[player]));auto priv=py::cast<py::dict>(kag_unit::clone(obs["private"]));py::list cs=commands(action);py::dict demand;for(py::handle ch:cs){auto c=py::cast<py::sequence>(ch);if(py::len(c)>1&&py::cast<std::string>(c[0])=="PLANT"){py::object item=py::reinterpret_borrow<py::object>(c[1]);demand[item]=(demand.contains(item)?as_int(demand[item]):0)+1;}}auto seeds=py::cast<py::dict>(priv["seeds"]);py::set blocked;for(auto kv:demand){int have=seeds.contains(kv.first)?as_int(seeds[kv.first]):0;if(as_int(kv.second)>have)blocked.add(kv.first);}auto invs=py::cast<py::sequence>(priv["inventories"]);int n=std::min((int)py::len(cs),(int)py::len(invs));for(int actor=0;actor<n;++actor){auto c=py::cast<py::sequence>(cs[actor]);if(py::len(c)>1&&py::cast<std::string>(c[0])=="PLANT"&&blocked.contains(c[1]))continue;kag_unit::apply(farm,priv,actor,cs[actor],10,day,24,100);}return py::make_tuple(farm,priv);}
static py::dict future_action(py::dict obs,int offset,py::object impl){int step=as_int(obs["step"])+offset,player=as_int(obs["player"]);py::object chassis=impl.attr("chassis");auto players=py::cast<py::dict>(chassis.attr("players"));auto native=py::cast<py::dict>(players[py::int_(player)]);py::object route=step>=648?py::object(py::int_(2)):py::reinterpret_borrow<py::object>(native["route"]);auto routes=py::cast<py::dict>(chassis.attr("routes"));auto tape=py::cast<py::sequence>(routes[route]);return py::cast<py::dict>(tape[step]);}
static int r128_food_need(py::dict obs,py::dict farm_in,py::dict private_in,int actor,py::object impl){py::dict farm=py::cast<py::dict>(kag_unit::clone(farm_in)),priv=py::cast<py::dict>(kag_unit::clone(private_in));int step=as_int(obs["step"]),day=step/24,missing=0,stop=std::min(5,24-step%24);for(int offset=1;offset<stop;++offset){py::dict fa=future_action(obs,offset,impl);py::list cs=commands(fa);py::object command;if(actor<py::len(cs))command=py::reinterpret_borrow<py::object>(cs[actor]);else{py::list p;p.append("PASS");command=p;}auto c=py::cast<py::sequence>(command);if(py::len(c)>=2&&py::cast<std::string>(c[0])=="PICKUP"&&py::cast<std::string>(c[1])=="WHEAT")break;bool feed=py::len(c)==1&&py::cast<std::string>(c[0])=="FEED";if(feed){auto hands=py::cast<py::sequence>(farm["hands"]);py::sequence p=actor==0?py::cast<py::sequence>(farm["farmer"]):py::cast<py::sequence>(hands[actor-1]);int x=as_int(p[0]),y=as_int(p[1]);auto tiles=py::cast<py::sequence>(farm["tiles"]);auto row=py::cast<py::sequence>(tiles[y]);py::handle th=row[x];auto invs=py::cast<py::sequence>(priv["inventories"]);auto inv=py::cast<py::dict>(invs[actor]);bool hungry=false;if(py::isinstance<py::dict>(th)){auto tile=py::cast<py::dict>(th);hungry=tile.contains("animal")&&!tile["animal"].is_none()&&truthy(tile["animal"])&&(!tile.contains("fed_today")||!truthy(tile["fed_today"]));}int wheat=inv.contains("WHEAT")?as_int(inv["WHEAT"]):0;if(hungry&&wheat<=0){inv["WHEAT"]=1;++missing;}}kag_unit::apply(farm,priv,actor,command,10,day,24,100);}return missing;}
}
PYBIND11_MODULE(_kaggriculture_service,m){m.def("r127_fields",&r127_fields);m.def("r128_food_need",&r128_food_need);}
